import json, hashlib
from access import Authenticator, Sessions, ResourceError

def compact(o): return json.dumps(o,ensure_ascii=False,separators=(',',':'))
def digest(o): return hashlib.sha256(compact(o).encode()).hexdigest()
def seal(doc):
    head={'版本':doc['版本'],'时刻':doc['时刻'],'用户':doc['用户']}
    doc['摘要']=digest(head)
    return compact(doc)+'\n'

